import { randomBytes } from 'node:crypto';
import { passwordProblems } from '../../modules/auth/password-policy';
import { FULL_SIZE, MIN_ROSTER } from './plan';

/**
 * Configuration of the staging seed (`pnpm db:seed:staging`), read from the environment. Pure: no I/O,
 * so the contract is unit-tested (apps/api/test/seed-staging.test.ts).
 *
 * STAGING_LOGINS (JSON, generated by the infrastructure and injected from Google Secret Manager):
 *   {"workspace":"kestrel","logins":[{"role":"owner","email":"…","password":"…"}, …]}
 * with exactly one login for each of the five roles below. Passwords are used exactly as given and are
 * never printed. Only local development (APP_ENV unset, dev or test) may omit it: the seed then uses the
 * default emails and prints freshly generated passwords once.
 */
export const LOGIN_ROLES = ['owner', 'hr_admin', 'payroll_admin', 'manager', 'employee'] as const;
export type LoginRole = (typeof LOGIN_ROLES)[number];

export interface StagingLogin {
  role: LoginRole;
  email: string;
  password: string;
}

export interface StagingConfig {
  workspace: string;
  logins: StagingLogin[];
  /** True when the passwords were generated here (local development only): print them once. */
  generated: boolean;
  appEnv: string;
  /** Number of people on the roster (default 300; smaller only to keep CI fast). */
  size: number;
}

export const DEFAULT_WORKSPACE = 'kestrel';
export const COMPANY_NAME = 'Kestrel Fictional Group Ltd';
export { FULL_SIZE };
/** Smallest roster that still has every team (execs, every team lead and the manager's full team). */
export const MIN_SIZE = MIN_ROSTER;

const LOCAL_ENVS = new Set(['dev', 'test']);
const SLUG = /^[a-z0-9](?:[a-z0-9-]{1,38}[a-z0-9])$/;
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

const DEFAULT_LOCAL_PART: Record<LoginRole, string> = {
  owner: 'owner',
  hr_admin: 'hr.admin',
  payroll_admin: 'payroll',
  manager: 'manager',
  employee: 'employee',
};

export const defaultEmail = (role: LoginRole, workspace = DEFAULT_WORKSPACE) =>
  `${DEFAULT_LOCAL_PART[role]}@${workspace}.example.test`;

export class StagingConfigError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'StagingConfigError';
  }
}

/** The seed never runs against production, whatever else is configured. */
export function assertSeedAllowed(env: NodeJS.ProcessEnv): void {
  if (env.APP_ENV === 'prod') throw new StagingConfigError('The staging seed never runs when APP_ENV=prod');
  if (env.CELL_REGION && env.CELL_REGION !== 'uk')
    throw new StagingConfigError(
      `The staging tenant is homed in the UK cell; this process is configured for ${env.CELL_REGION}`,
    );
}

/** A random password that satisfies the password policy (local development only). */
export function generatePassword(email?: string): string {
  for (;;) {
    const pw = randomBytes(18).toString('base64url');
    if (!passwordProblems(pw, { companyName: COMPANY_NAME, workspaceSlug: DEFAULT_WORKSPACE, email }).length)
      return pw;
  }
}

function parseLogins(raw: string): { workspace: string; logins: StagingLogin[] } {
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch {
    throw new StagingConfigError('STAGING_LOGINS is not valid JSON');
  }
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed))
    throw new StagingConfigError('STAGING_LOGINS must be a JSON object');
  const o = parsed as { workspace?: unknown; logins?: unknown };
  const workspace = o.workspace === undefined ? DEFAULT_WORKSPACE : o.workspace;
  if (typeof workspace !== 'string' || !SLUG.test(workspace))
    throw new StagingConfigError('STAGING_LOGINS.workspace must be a workspace slug');
  if (!Array.isArray(o.logins)) throw new StagingConfigError('STAGING_LOGINS.logins must be an array');
  const logins: StagingLogin[] = [];
  for (const [i, l] of o.logins.entries()) {
    const x = l as { role?: unknown; email?: unknown; password?: unknown } | null;
    if (!x || typeof x !== 'object')
      throw new StagingConfigError(`STAGING_LOGINS.logins[${i}] must be an object`);
    if (typeof x.role !== 'string' || !(LOGIN_ROLES as readonly string[]).includes(x.role))
      throw new StagingConfigError(
        `STAGING_LOGINS.logins[${i}].role must be one of ${LOGIN_ROLES.join(', ')}`,
      );
    if (typeof x.email !== 'string' || x.email.length > 254 || !EMAIL.test(x.email))
      throw new StagingConfigError(`STAGING_LOGINS.logins[${i}].email is not an email address`);
    if (typeof x.password !== 'string')
      throw new StagingConfigError(`STAGING_LOGINS.logins[${i}].password must be a string`);
    logins.push({ role: x.role as LoginRole, email: x.email.toLowerCase(), password: x.password });
  }
  return { workspace, logins };
}

/** Every role exactly once, distinct emails, and passwords the app's own policy accepts (never echoed). */
function validateLogins(workspace: string, logins: StagingLogin[]): void {
  for (const role of LOGIN_ROLES) {
    const n = logins.filter((l) => l.role === role).length;
    if (n !== 1) throw new StagingConfigError(`STAGING_LOGINS needs exactly one ${role} login (found ${n})`);
  }
  if (logins.length !== LOGIN_ROLES.length)
    throw new StagingConfigError(`STAGING_LOGINS must have exactly ${LOGIN_ROLES.length} logins`);
  if (new Set(logins.map((l) => l.email)).size !== logins.length)
    throw new StagingConfigError('STAGING_LOGINS emails must be distinct');
  for (const l of logins) {
    const problems = passwordProblems(l.password, {
      companyName: COMPANY_NAME,
      workspaceSlug: workspace,
      email: l.email,
    });
    if (problems.length)
      throw new StagingConfigError(
        `The ${l.role} password does not meet the password policy (${problems.join(', ')})`,
      );
  }
}

export function stagingConfigFromEnv(env: NodeJS.ProcessEnv): StagingConfig {
  assertSeedAllowed(env);
  const appEnv = env.APP_ENV ?? 'dev';
  const size = env.STAGING_SEED_EMPLOYEES ? Number(env.STAGING_SEED_EMPLOYEES) : FULL_SIZE;
  if (!Number.isInteger(size) || size < MIN_SIZE || size > 2000)
    throw new StagingConfigError(`STAGING_SEED_EMPLOYEES must be a whole number from ${MIN_SIZE} to 2000`);
  const raw = env.STAGING_LOGINS?.trim();
  if (raw) {
    const { workspace, logins } = parseLogins(raw);
    validateLogins(workspace, logins);
    // a stable order (the roles' order) so output and processing never depend on the JSON order
    logins.sort((a, b) => LOGIN_ROLES.indexOf(a.role) - LOGIN_ROLES.indexOf(b.role));
    return { workspace, logins, generated: false, appEnv, size };
  }
  if (!LOCAL_ENVS.has(appEnv))
    throw new StagingConfigError(`STAGING_LOGINS is required when APP_ENV=${appEnv}`);
  return {
    workspace: DEFAULT_WORKSPACE,
    logins: LOGIN_ROLES.map((role) => ({
      role,
      email: defaultEmail(role),
      password: generatePassword(defaultEmail(role)),
    })),
    generated: true,
    appEnv,
    size,
  };
}
